  <React.StrictMode>
    <GoogleOAuthProvider clientId="140116568849-0mmjr1aqfp2cnfrtlb17kgqtv00fl1i4.apps.googleusercontent.com">
      <App />
    </GoogleOAuthProvider>
  </React.StrictMode>
);
